insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6223, 10, 'Investitionskosten der Heime nicht mehr den Bewohnern anlasten', 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'gemischt', null, 'bund', null, true, null),
  (6224, 10, 'Private Pflegeversicherung in den Finanzausgleich einbeziehen', 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'gemischt', null, 'bund', null, true, null),
  (6225, 10, 'Private und betriebliche Pflegezusatzvorsorge fördern', 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6226, 10, 'Leistungen für häusliche Pflege zu einem flexiblen Budget bündeln', 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'gemischt', null, 'bund', null, true, null),
  (6227, 10, 'Lohnersatz für pflegende Angehörige, die ihre Arbeitszeit reduzieren', 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6228, 10, 'Tages-, Nacht- und Kurzzeitpflege sowie Beratung ausbauen', 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'gemischt', null, 'bund', null, true, null),
  (6229, 10, 'Arbeitsbedingungen in der Pflege verbessern (Personalbemessung, verlässliche Dienstpläne, weniger Dokumentation)', 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6230, 10, 'Ausgestiegene Pflegekräfte zurückgewinnen', 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'gemischt', null, 'bund', null, true, null),
  (6231, 10, 'Pflegekräfte im Ausland anwerben, Anerkennung beschleunigen', 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'gemischt', null, 'bund', null, true, null),
  (6232, 10, 'Mehr Befugnisse und Aufstiegswege für Pflegefachpersonen', 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'gemischt', null, 'bund', null, true, null),
  (6233, 10, 'Bessere Bezahlung in der Pflege', 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6234, 10, 'Prävention und Reha, um Pflegebedürftigkeit hinauszuzögern', 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6235, 10, 'Pflegeausbildung verbessern und ausbauen', 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6447, 10, 'Land übernimmt die Investitionskosten der Heime (Land)', 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'gemischt', null, 'land', null, true, null),
  (6448, 10, 'Land beteiligt sich an den Investitionskosten, ohne Umfang (Land)', 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'gemischt', null, 'land', null, true, null),
  (6449, 10, 'Landesprogramm für Investitionen und Sanierung von Pflegeeinrichtungen (Land)', 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'gemischt', null, 'land', null, true, null)
