-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 10 „Pflege“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 10;
delete from public.abdeckung where thema_id = 10;
delete from public.pruef_einheiten where thema_id = 10;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 10 and id not in (6223, 6224, 6225, 6226, 6227, 6228, 6229, 6230, 6231, 6232, 6233, 6234, 6235, 6447, 6448, 6449);

  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (6236, 10, 11, null, 'Pflegezusatzversicherungen steuerlich besser absetzbar machen (Prüfauftrag)', '{1002}', 6225, 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6237, 10, 11, null, 'Pflegebudget, das flexibel für pflegerische Leistungen eingesetzt werden kann', '{1004}', 6226, 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6238, 10, 11, null, 'Pflegebedürftigkeit durch Prävention und Reha aufschieben', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6239, 10, 11, null, 'Planbare Einsatzzeiten, Springerpools, Aufstiegsmöglichkeiten', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6240, 10, 11, null, 'Pflegekräfte im Ausland anwerben', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6241, 10, 11, null, 'Rolle der Pflegefachpersonen stärken, Dokumentation vereinfachen', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6242, 10, 12, null, 'Pflegekosten-Deckel: Eigenanteile in der stationären Pflege auf 1.000 Euro im Monat begrenzen', '{1002}', null, 2, 2, null, 'Ein Deckel senkt die pflegebedingten Eigenanteile direkt und für alle Heimbewohner; Unterkunft, Verpflegung und Investitionskosten bleiben aber, und die Mehrkosten von mehreren Milliarden Euro im Jahr müssen über Beiträge oder Steuern finanziert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6243, 10, 12, null, 'Investitionskosten der Heime nicht mehr vollständig auf die Bewohner umlegen', '{1005}', 6223, 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6244, 10, 12, null, 'Private Pflegeversicherungen in den Risikostrukturausgleich einbeziehen', '{1002}', 6224, 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6245, 10, 12, null, 'Familienpflegezeit und Familienpflegegeld analog zum Elterngeld', '{1004}', 6227, 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6246, 10, 12, null, 'Beratung und Anlaufstellen, Tages- und Nachtpflege ausbauen', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6247, 10, 12, null, 'Bundeseinheitliche bedarfsgerechte Personalausstattung', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6248, 10, 12, null, 'Tarifgebundene Gehälter refinanzieren', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6249, 10, 12, null, 'Befugnisse von Pflegefachpersonen erweitern', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6250, 10, 12, null, 'Weltweite Anwerbung und Integration von Fachkräften ausbauen', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6251, 10, 12, null, 'Praxisnahe und kostenfreie Ausbildung in den Gesundheitsfachberufen', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (6252, 10, 13, null, 'Angebote im Quartier fördern, um Pflegebedürftigkeit hinauszuzögern', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=91', null, 'gemischt', '2026-09-29', false, true, null),
  (6253, 10, 13, null, 'Zeitlich begrenzter Lohnersatz und Rentenbeiträge für Angehörige, die für die Pflege Arbeitszeit reduzieren', '{1004}', 6227, 2, 2, null, 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6254, 10, 13, null, 'Tages- und Kurzzeitpflege stärken und ausbauen', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6255, 10, 13, null, 'Leistungen flexibel kombinieren, etwa über ein Pflegebudget', '{1004}', 6226, 2, 3, null, 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6256, 10, 13, null, 'Rückkehroffensive für ausgestiegene Pflegekräfte', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6257, 10, 13, null, 'Höhere Personalschlüssel', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6258, 10, 13, null, 'Mehr Kompetenzen und Aufstiegschancen für den Pflegeberuf', '{1001}', 6232, 1, 3, null, 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6259, 10, 13, null, 'Ausbildungsbedingungen verbessern, Pflegeassistenz bundesweit einheitlich regeln', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6260, 10, 13, null, 'Ausgleich zwischen gesetzlicher und privater Pflegeversicherung auf dem Weg zur Pflegebürgerversicherung', '{1002}', 6224, 1, 2, null, 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', null, 'gemischt', '2026-09-29', false, true, null),
  (6261, 10, 14, null, 'Pflegeanbieter von doppelten Prüfungen und unnötigen Dokumentationspflichten befreien', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6262, 10, 14, null, 'Niedrigschwellige Beratung ausbauen, auch für pflegende Kinder und Jugendliche', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6263, 10, 14, null, 'Mehr Pflegefachkräfte im In- und Ausland gewinnen, Anerkennung drastisch vereinfachen', '{1001}', 6231, 2, 2, null, 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (6264, 10, 14, null, 'Pflegepersonal durch digitale Anwendungen, Automatisierung und Robotik entlasten', '{1001}', null, 1, 3, null, 'Digitale Dokumentation und Assistenzsysteme können Pflegekräfte von Routinearbeit entlasten; wie viel Zeit das spart und ob Robotik in der Pflege breit einsetzbar ist, ist bisher kaum untersucht. Der Bund kann es fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6265, 10, 14, null, 'Soziale Pflegeversicherung um eine kapitalgedeckte Komponente ergänzen', '{1003}', null, 1, 2, null, 'Ein Kapitalstock kann die Beitragssätze dämpfen, wenn die Zahl der Pflegebedürftigen steigt; der bestehende Pflegevorsorgefonds ist klein, und ein neuer Kapitalstock wirkt erst langfristig. Per Bundesgesetz umsetzbar, der Aufbau braucht zusätzliche Mittel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6266, 10, 14, null, 'Anreize für private Pflegevorsorge, betriebliche Pflegevorsorge der Betriebsrente gleichstellen', '{1002}', 6225, 1, 3, null, 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6267, 10, 15, null, 'Häusliche Pflege durch Angehörige deutlich höher honorieren', '{1004}', null, 1, 2, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Das Programm nennt keinen Betrag; die Mehrkosten trägt die Pflegeversicherung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (6268, 10, 15, null, 'Ambulante und befristete stationäre Angebote für pflegende Angehörige ausweiten', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (6269, 10, 15, null, 'Ausgebildete Pflegekräfte durch bessere Bedingungen in den Beruf zurückholen', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=113', null, 'gemischt', '2026-09-29', false, true, null),
  (6270, 10, 16, null, 'Solidarische Pflegevollversicherung, die alle pflegerischen Leistungen abdeckt', '{1002}', null, 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, die Finanzierung über eine Bürgerversicherung ist politisch und rechtlich offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'belegt', '2026-09-29', false, true, null),
  (6271, 10, 16, null, 'Bundesweite Offensive zur Rückanwerbung von Pflegekräften', '{1001}', 6230, 2, 2, null, 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (6272, 10, 16, null, 'Ausbildungsoffensive', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (6273, 10, 16, null, 'Gute Arbeitsbedingungen und Entlastung der Beschäftigten in Pflegeeinrichtungen', '{1001}', 6229, 2, 2, null, 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6274, 10, 16, null, 'Länder verpflichten, Investitions- und Ausbildungskosten zu übernehmen; Kosten für Unterkunft und Verpflegung deckeln', '{1002,1005}', 6223, 2, 1, null, 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6275, 10, 16, null, 'Schonvermögen für Pflegebedürftige erhöhen', '{1002}', null, 1, 3, null, 'Ein höheres Schonvermögen schützt Erspartes, bevor die Sozialhilfe einspringt; die Eigenanteile selbst sinken dadurch nicht. Per Bundesgesetz umsetzbar, die Mehrkosten tragen die Sozialhilfeträger.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6276, 10, 16, null, 'Lohnlücke zwischen Alten- und Krankenpflege von rund 300 Euro schließen', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6277, 10, 16, null, 'Sechs Wochen Freistellung mit vollem, arbeitgeberfinanziertem Lohnausgleich beim ersten Pflegefall in der Familie', '{1004}', null, 1, 2, null, 'Eine bezahlte Freistellung hilft Angehörigen, einen neuen Pflegefall zu organisieren; die langfristige Belastung bleibt. Die Kosten tragen die Arbeitgeber, was vor allem kleine Betriebe belastet.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6278, 10, 16, null, 'Wohnortnahe, nichtkommerzielle Tages- und Kurzzeitpflege', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (6440, 10, 17, null, 'Pflegevollversicherung, überwiegend aus Steuermitteln finanziert', '{1002}', null, 3, 1, null, 'Eine Vollversicherung beseitigt die pflegebedingten Eigenanteile vollständig; Unterkunft und Verpflegung bleiben. Die Mehrkosten liegen bei deutlich über 10 Milliarden Euro im Jahr, eine Finanzierung überwiegend aus Steuern ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'belegt', '2026-09-29', false, true, null),
  (6441, 10, 17, null, 'Mehr Pflegepersonal ausbilden', '{1001}', 6235, 1, 3, null, 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6442, 10, 17, null, 'Bessere Bezahlung in der Pflege', '{1001}', 6233, 2, 2, null, 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6443, 10, 17, null, 'Pflegegeld deutlich erhöhen, orientiert an der Bezahlung professioneller Pflegekräfte', '{1004}', null, 1, 1, null, 'Ein höheres Pflegegeld erkennt die Arbeit pflegender Angehöriger an und entlastet sie finanziell, verringert aber nicht ihre zeitliche und körperliche Belastung. Eine Orientierung am Lohn von Pflegekräften würde ein Vielfaches kosten, die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-09-29', false, true, null),
  (6450, 10, 11, 'MV', 'Landesbeteiligung an Investitionskosten und Ausbildungsumlage, Landesinvestitionsprogramm für Pflegeeinrichtungen', '{1005}', 6448, 1, 3, null, 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true, null),
  (6451, 10, 12, 'ST', 'Investitionen in Pflegeeinrichtungen fördern, wo die Versorgung sonst nicht gesichert wäre', '{1005}', 6449, 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=13', null, 'gemischt', '2026-09-29', false, true, null),
  (6452, 10, 13, 'ST', 'Land übernimmt Investitions- und Ausbildungskosten aus dem Eigenanteil', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=86', null, 'gemischt', '2026-09-29', false, true, null),
  (6453, 10, 15, 'BE', 'Investitionskostenzuschuss des Landes auf 300 Euro je Person und Monat erhöhen; 40.000 Euro je neuem Heimplatz', '{1005}', null, 2, 2, null, 'Ein Zuschuss von 300 Euro im Monat deckt einen großen Teil der Investitionskosten und senkt den Eigenanteil spürbar; das Programm nennt keine Finanzierung, und Berlin müsste dafür dauerhaft einen dreistelligen Millionenbetrag im Jahr aufbringen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=71', null, 'gemischt', '2026-09-29', false, true, null),
  (6454, 10, 16, 'ST', 'Land übernimmt die Investitionskosten der Pflegeeinrichtungen vollständig', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (6455, 10, 16, 'MV', 'Sanierungen vollstationärer Einrichtungen durch ein Investitionsprogramm unterstützen', '{1005}', 6449, 1, 3, null, 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', null, 'gemischt', '2026-09-29', false, true, null),
  (6456, 10, 16, 'BE', 'Pflegewohngeld: Land übernimmt Investitionskosten für Heimbewohner', '{1005}', null, 2, 2, null, 'Ein Pflegewohngeld übernimmt die Investitionskosten für Bewohner, die sie nicht selbst tragen können, und entlastet sie direkt; wer mehr Einkommen oder Vermögen hat, zahlt weiter. Das Land kann es selbst einführen, die Kosten muss es dauerhaft tragen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=140', null, 'gemischt', '2026-09-29', false, true, null),
  (6457, 10, 17, 'MV', 'Eigenanteile senken: Land übernimmt die Investitionskosten auf Grundlage der Landespflegeplanung', '{1005}', 6447, 2, 2, null, 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=66', null, 'gemischt', '2026-09-29', false, true, null),
  (7231, 10, 12, null, 'Digitale Produkte und Beratung in der Pflege nutzen, um Prävention zu fördern und Pflegebedürftigkeit vorzubeugen', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null),
  (8532, 10, 18, null, 'Betreuungsangebot für Pflegebedürftige deutlich ausbauen, damit niemand zu unbezahlter Sorgearbeit gezwungen ist', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', null, 'gemischt', '2026-10-07', false, true, null),
  (8616, 10, 18, 'MV', 'Gezielte Förderung kommunaler, genossenschaftlicher und quartiersnaher Pflegeeinrichtungen, um die Versorgung vor Ort zu sichern und Pflege bezahlbar zu halten.', '{1005}', null, 1, 3, null, 'Landesförderung für bestimmte Träger kann Kosten dämpfen, die Heime an Bewohner weitergeben; Art und Umfang der Förderung bleiben offen, und kommunale oder gemeinnützige Heime sind laut Daten nicht günstiger als private. Das Land kann ein Programm selbst auflegen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=33', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8617, 10, 18, 'ST', 'Investitionskostenförderung des Landes für Pflegeeinrichtungen ausbauen, damit Bewohner weniger zahlen.', '{1005}', 6448, 1, 3, null, 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=41', null, 'gemischt', '2026-10-08', false, true, null);

select setval(pg_get_serial_sequence('public.massnahmen', 'id'), (select max(id) from public.massnahmen));

